from collections import deque
nums = [1,3,2,5]
q = deque()
answer = []
for i in range(4):
    if q and q[0] <= i-2:
        q.popleft()
    while q and nums[q[-1]] <= nums[i]:
        q.pop()
    q.append(i)
    if i >= 1:
        answer.append(nums[q[0]])
return answer

